from __future__ import annotations

from pathlib import Path
from typing import Any

from .runtime_config import RUNTIME_CONFIG_PATH, web_url


def build_agent_manifest(root: str | Path | None = None) -> dict[str, Any]:
    """Return the stable contract for agents and UI action parity."""
    from .mcp_server import list_mcp_tools

    project_root = str(root or "")
    return {
        "ok": True,
        "schema": "question_research_agent_manifest.v1",
        "project_root": project_root,
        "runtime_config": str(RUNTIME_CONFIG_PATH),
        "web_url": web_url(),
        "purpose": "Stable contract for operating question-research-poc through UI, CLI, MCP, and Web API without guessing ports or bypassing review gates.",
        "codex_deep_research_default": {
            "cli": ".\\scripts\\research-poc.ps1 deep-research --project <project> --query <query> --mode academic --max-results 8",
            "delegation": "QRP preflights ai-research-workflow, calls /v1/agent/research, imports candidates, and leaves all source/evidence review gates human-confirmed.",
            "fallback_policy": "If ai-research-workflow is unreachable, report the bridge failure; do not silently switch to manual web search.",
        },
        "codex_research_loop_default": {
            "cli": ".\\scripts\\research-poc.ps1 research-loop --project <project> --query <query> --mode academic --rounds 3 --max-results 8 --max-queries-per-round 3",
            "delegation": "QRP controls gap detection and loop state; ai-research-workflow performs live research jobs. Loop output remains candidate-only and human-review-gated.",
            "stop_states": ["ready_for_human_review", "needs_more_manual_input", "blocked_bridge_down", "stopped_budget_limit"],
        },
        "backend_readiness_contract": {
            "current_truth": "get_tool_bridge_status",
            "modes": ["full_research", "degraded_local_only", "blocked"],
            "full_research": "ai-research-workflow and SearXNG dependency are live; deep-research/search actions may be planned for explicit live execution.",
            "degraded_local_only": "Pause 9082/8928-dependent live search; use cached artifacts, explicit URL web fetch, local docs, existing video bundles, and human-reviewed candidate imports.",
            "blocked": "Do not run external research actions; restore backend services or continue only with human review of existing artifacts.",
        },
        "sync_safety_contract": {
            "cli": ".\\scripts\\research-poc.ps1 audit-sync-safety --repo <repo>",
            "api": "/api/sync-safety",
            "mcp": "audit_sync_safety",
            "rule": "Run before staging or GitHub sync; never stage projects/, emergency-backups/, runtime logs, provider profiles, API keys, login state, or source-restricted research artifacts.",
        },
        "mcp_tools": list_mcp_tools(),
        "ui_actions": _ui_actions(project_root),
        "read_artifact_endpoints": [
            {"artifact": "project_status", "api": "/api/project", "cli": "get-project-status", "mcp": "get_project_status"},
            {"artifact": "project_overview", "api": "/api/project-overview", "cli": "get-project-overview", "mcp": "get_project_overview"},
            {"artifact": "gate_details", "api": "/api/gate-details", "cli": "get-gate-details", "mcp": "get_gate_details"},
            {"artifact": "review_queue", "api": "/api/review-queue", "cli": "get-review-queue", "mcp": "get_review_queue"},
            {"artifact": "research_gap_analysis", "api": "/api/analyze-research-gaps", "cli": "analyze-research-gaps", "mcp": "analyze_research_gaps"},
            {"artifact": "research_loops", "api": "/api/research-loops", "cli": "list-research-loops", "mcp": "list_research_loops"},
            {"artifact": "research_loop", "api": "/api/research-loop", "cli": "read-research-loop", "mcp": "read_research_loop"},
            {"artifact": "research_loop_review_pack", "api": "/api/export-research-loop-review-pack", "cli": "export-research-loop-review-pack", "mcp": "export_research_loop_review_pack"},
            {"artifact": "tool_bridge_status", "api": "/api/tool-bridge-status", "cli": "get-tool-bridge-status", "mcp": "get_tool_bridge_status"},
            {"artifact": "sync_safety", "api": "/api/sync-safety", "cli": "audit-sync-safety", "mcp": "audit_sync_safety"},
            {"artifact": "bridge_runs", "api": "/api/bridge-runs", "cli": "list-bridge-runs", "mcp": "list_bridge_runs"},
            {"artifact": "bridge_action_plan", "api": "/api/plan-bridge-action", "cli": "plan-bridge-action", "mcp": "plan_bridge_action"},
            {"artifact": "bridge_action_run", "api": "/api/run-bridge-action", "cli": "run-bridge-action", "mcp": "run_bridge_action"},
            {"artifact": "completeness_audit", "api": "/api/completeness-audit", "cli": "audit-completeness", "mcp": "audit_completeness"},
            {"artifact": "cockpit_readiness", "api": "/api/cockpit-readiness", "cli": "audit-cockpit-readiness", "mcp": "audit_cockpit_readiness"},
            {"artifact": "final_answer_export", "api": "/api/export-final-answer", "cli": "export-final-answer", "mcp": "export_final_answer"},
            {"artifact": "work_queue", "api": "/api/work-queue", "cli": "list-work-queue", "mcp": "list_work_queue"},
            {"artifact": "graph_candidates", "api": "/api/graph-candidates", "cli": "list-graph-candidates", "mcp": "list_graph_candidates"},
            {"artifact": "workflow_artifact", "api": "", "cli": "read-workflow-artifact", "mcp": "read_workflow_artifact"},
        ],
        "human_review_boundaries": [
            "Source quality review must remain human-confirmed.",
            "Candidate evidence must not be automatically promoted to verified.",
            "Poor-source evidence must be treated as a lead or explicitly reviewed.",
            "Logseq writeback must go through a generated review handoff; direct write is forbidden by default.",
            "External tools are delegated modules; this controller does not reimplement search, fetch, video extraction, OCR, ASR, or multimodal analysis.",
            "Work queue execution only runs explicit allowlisted tool_action entries; ordinary command text is preview/manual only.",
            "Bridge actions can only call allowlisted bridge functions; they do not execute arbitrary shell commands.",
            "Graph candidates require explicit human acceptance before reviewed graph export or knowledge-base writeback.",
            "Final-answer export is blocked unless completeness audit passes, unless explicitly marked incomplete.",
        ],
        "forbidden_operations": [
            "Do not auto-mark source quality as good/mixed/poor without explicit human confirmation.",
            "Do not auto-mark evidence as verified from imported candidates.",
            "Do not auto-accept graph candidates.",
            "Do not present draft or incomplete export as a final answer.",
            "Do not write directly to Logseq API from this controller.",
            "Do not execute arbitrary shell commands through bridge_action or work queue.",
            "Do not implement search, webpage fetching, video processing, ASR/OCR, or multimodal analysis inside this controller.",
            "Do not treat Vane/Perplexica messages as verified evidence; import them only as candidate context and candidate sources.",
            "Do not treat external Deep Research provider reports as verified evidence; import them only as candidate context and candidate sources.",
            "Do not automate provider login, CAPTCHA, payment walls, or private pages; browser automation requires explicit human authorization.",
            "Do not hardcode or duplicate the WebUI port outside config/runtime.json.",
            "Do not store API keys or tokens in generated artifacts, docs, registry, or manifests.",
            "Do not stage or commit projects/, emergency-backups/, runtime logs, provider/browser profiles, login state, or source-restricted research artifacts.",
            "Do not trust registry/discovery metadata as proof that a backend is currently live; use get_tool_bridge_status.",
        ],
        "recommended_agent_flow": [
            "get_project_status",
            "get_project_overview",
            "get_gate_details",
            "get_review_queue",
            "get_tool_bridge_status",
            "audit_sync_safety before staging, committing, creating a remote, or GitHub sync",
            "list_bridge_runs",
            "read_bridge_run",
            "For Codex/user requests phrased as deep search or deep research, prefer CLI deep-research so ai-research-workflow is actually invoked and imported candidates are review-gated.",
            "Before multi-round research, run analyze_research_gaps; only run research_loop when backend mode is full_research and actionable search gaps exist.",
            "For multi-round research, unresolved claims, or repeated search gaps, use research_loop so gap detection, follow-up queries, job traces, stop reasons, and review packs are recorded.",
            "Use list_research_loops/read_research_loop/export_research_loop_review_pack to inspect loop artifacts before final-answer-like synthesis.",
            "retry_bridge_run_plan",
            "plan_bridge_action",
            "run_bridge_action only for allowlisted bridge actions; default dry-run unless execute is explicit",
            "vane_perplexica_status/plan_vane_perplexica_search/run_vane_perplexica_search when a fast optional candidate-source search bridge is explicitly useful",
            "plan_external_researcher_session/import_external_researcher_report/export_external_researcher_bundle when external Deep Research reports should enter the candidate review gate",
            "prepare_external_researcher_login_profiles/check_external_researcher_automation_profiles before any external provider automation; do not run provider automation from queue by default",
            "run_omnigent_external_research_poc when testing the local Omnigent-style orchestrator spec + inbox + external researcher automation flow",
            "enqueue_bridge_actions to convert clear runbook bridge actions into queue items",
            "audit_cockpit_readiness when checking controller capability gaps",
            "generate_graph_candidates/list_graph_candidates when graph review is needed",
            "audit_completeness before final-answer-like output",
            "export_final_answer only after audit_completeness is ready, or with explicit incomplete marking",
            "run_next_step for agent-safe gates only",
            "run_work_queue_item only for explicit tool_action entries; default dry-run",
            "export_research_pack or create_logseq_review_handoff after gates are reviewed",
        ],
    }


