def _action(
    action_id: str,
    label: str,
    api: str,
    cli: str,
    mcp: str,
    agent_callable: bool,
    human_review_boundary: bool,
) -> dict[str, Any]:
    return {
        "id": action_id,
        "label": label,
        "api": api,
        "cli": cli,
        "mcp": mcp,
        "agent_callable": agent_callable,
        "human_review_boundary": human_review_boundary,
    }
